from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

CENT = Decimal('0.01')
ZERO = Decimal('0.00')


def _decimal_value(value):
    if isinstance(value, bool):
        raise ValueError('Boolean is not a monetary value')
    try:
        result = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError):
        raise ValueError('malformed monetary value')
    if not result.is_finite():
        raise ValueError('monetary value must be finite')
    return result


def money(value):
    result = _decimal_value(value)
    try:
        return result.quantize(CENT, rounding=ROUND_HALF_UP)
    except InvalidOperation:
        raise ValueError('monetary value cannot be quantized')


def refund_original(order, refund_id, amount, role, processed_refund_ids):
    if role != 'support_admin':
        raise PermissionError('support_admin role required')
    if order['status'] != 'active':
        raise ValueError('order is not active')
    if refund_id in processed_refund_ids:
        return ZERO

    raw_amount = _decimal_value(amount)
    remaining = money(order['total']) - money(order['refunded'])
    if raw_amount <= ZERO or raw_amount > remaining:
        raise ValueError('refund amount is outside remaining balance')

    quantized_amount = money(raw_amount)
    if quantized_amount <= ZERO or quantized_amount > remaining:
        raise ValueError('refund amount is outside remaining balance')

    processed_refund_ids.add(refund_id)
    order['refunded'] = money(order['refunded']) + quantized_amount
    return quantized_amount

